import React from "react";

function Footer() {
  const openGitHub = () => {
    window.open("https://github.com/Marty207", "_blank", "noopener,noreferrer");
  };

  const openLinkedIn = () => {
    window.open(
      "https://www.linkedin.com/in/martin-donev-213377349/",
      "_blank",
      "noopener,noreferrer"
    );
  };

  return (
    <footer className="footer">
      <div className="footer-block">
        <h3>Martin Donev</h3>
        <p>Chicago, IL</p>
      </div>

      <div className="footer-block">
        <p><strong>Email:</strong> donev.martin@yahoo.com</p>
        <p><strong>Mobile:</strong> 224-535-0836</p>
      </div>

      <div className="footer-links">
        <button type="button" onClick={openGitHub}>GitHub</button>
        <button type="button" onClick={openLinkedIn}>LinkedIn</button>
      </div>
    </footer>
  );
}

export default Footer;
